answer_code:
#include <tuple>
#include <utility>

// tuple の全要素に f を適用する
template <class Tuple, class F>
void for_each_element(Tuple&& t, F&& f) {
    std::apply([&](auto&&... elems) { (f(elems), ...); }, std::forward<Tuple>(t));
}

// 全要素が述語 pred を満たすか (要素が 0 個なら true)
template <class Tuple, class Pred>
bool all_of_elements(Tuple&& t, Pred&& pred) {
    return std::apply(
        [&](auto&&... elems) { return (static_cast<bool>(pred(elems)) && ...); },
        std::forward<Tuple>(t));
}

