// T が「メンバ関数 size() を持つか」を判定する型特性
template <class T, class = void>
struct has_size : std::false_type {};

// TODO: std::void_t を使った部分特殊化を書き、size() を持つときだけ true_type にする

// size() があればその値を、無ければ fallback を返す
template <class T, std::enable_if_t<has_size<T>::value, int> = 0>
std::size_t size_or(const T& x, std::size_t) {
    return x.size();
