template <class Derived>
struct Comparable {
    const Derived& self() const { return static_cast<const Derived&>(*this); }

    bool operator==(const Derived& o) const { return !(self() < o) && !(o < self()); }
    bool operator!=(const Derived& o) const { return !(*this == o); }
    bool operator>(const Derived& o) const { return o < self(); }
    bool operator<=(const Derived& o) const { return !(o < self()); }
    bool operator>=(const Derived& o) const { return !(self() < o); }
};

struct Version : Comparable<Version> {
    int major_;
    int minor_;
    Version(int a, int b) : major_(a), minor_(b) {}

    bool operator<(const Version& o) const {
        return major_ != o.major_ ? major_ < o.major_ : minor_ < o.minor_;
    }
};

