#include <memory>
#include <type_traits>
#include <utility>

// area() を持つどんな型でも収められる入れ物
class AnyShape {
    // 外からは見えない共通インタフェース
    struct Concept {
        virtual ~Concept() = default;
        virtual double area() const = 0;
        virtual std::unique_ptr<Concept> clone() const = 0;
    };

    // 具体型 T ごとの実装
    template <class T>
    struct Model : Concept {
        T value;
        explicit Model(T v) : value(std::move(v)) {}
        double area() const override { return value.area(); }
        std::unique_ptr<Concept> clone() const override {
            return std::unique_ptr<Concept>(new Model(value));
        }
    };

    std::unique_ptr<Concept> self_;

public:
    template <class T,
              std::enable_if_t<!std::is_same<std::decay_t<T>, AnyShape>::value, int> = 0>
    AnyShape(T&& value)
        : self_(new Model<std::decay_t<T>>(std::forward<T>(value))) {}

    AnyShape(const AnyShape& other) : self_(other.self_->clone()) {}
    AnyShape& operator=(const AnyShape& other) {
        self_ = other.self_->clone();
        return *this;
    }

    double area() const { return self_->area(); }
};

