template <class Sig>
class Func;

template <class R, class... Args>
class Func<R(Args...)> {
    struct Concept {
        virtual ~Concept() = default;
        virtual R call(Args... args) const = 0;
    };

    template <class F>
    struct Model : Concept {
        F fn;
        explicit Model(F f) : fn(std::move(f)) {}
        R call(Args... args) const override { return fn(args...); }
    };

    std::unique_ptr<Concept> impl_;

public:
    Func() = default;

    template <class F,
              std::enable_if_t<!std::is_same<std::decay_t<F>, Func>::value, int> = 0>
    Func(F&& f) : impl_(new Model<std::decay_t<F>>(std::forward<F>(f))) {}

    R operator()(Args... args) const { return impl_->call(args...); }

    explicit operator bool() const { return impl_ != nullptr; }
};

