#include <cstddef>
#include <initializer_list>
#include <type_traits>
#include <vector>

// 式テンプレートの目印になる共通基底
struct ExprBase {};

class Vec : public ExprBase {
public:
    static int created;
    std::vector<double> data;

    Vec() { ++created; }
    Vec(std::initializer_list<double> init) : data(init) { ++created; }

    // 式から構築するときに初めて評価する
    template <class E, std::enable_if_t<std::is_base_of<ExprBase, E>::value &&
                                        !std::is_same<E, Vec>::value, int> = 0>
    Vec(const E& e) : data(e.size()) {
        for (std::size_t i = 0; i < e.size(); ++i) data[i] = e[i];
        ++created;
    }

    std::size_t size() const { return data.size(); }
    double operator[](std::size_t i) const { return data[i]; }
};
int Vec::created = 0;

// 「足し算」そのものを表す型。計算はまだしない。
template <class L, class R>
struct AddExpr : ExprBase {
    const L& l;
    const R& r;
    AddExpr(const L& a, const R& b) : l(a), r(b) {}

    std::size_t size() const { return l.size(); }
    double operator[](std::size_t i) const { return l[i] + r[i]; }
};

template <class L, class R,
          std::enable_if_t<std::is_base_of<ExprBase, L>::value &&
                           std::is_base_of<ExprBase, R>::value, int> = 0>
AddExpr<L, R> operator+(const L& l, const R& r) {
    return AddExpr<L, R>(l, r);
}

