#include <array>
#include <cstddef>

constexpr std::array<int, 256> make_popcount_table() {
    std::array<int, 256> table{};
    for (int i = 0; i < 256; ++i) {
        int count = 0;
        int v = i;
        while (v > 0) {
            count += v & 1;
            v >>= 1;
        }
        table[i] = count;
    }
    return table;
}

constexpr std::array<int, 256> kPopcount = make_popcount_table();

int popcount8(unsigned char b) {
    return kPopcount[b];
}

