#include <cstddef>
#include <memory>
#include <utility>

class Bytes {
public:
    explicit Bytes(std::size_t n) : data_(std::make_unique<int[]>(n)), size_(n) {}

    Bytes(const Bytes& o) : data_(std::make_unique<int[]>(o.size_)), size_(o.size_) {
        for (std::size_t i = 0; i < size_; ++i) data_[i] = o.data_[i];
    }

    friend void swap(Bytes& x, Bytes& y) noexcept {
        using std::swap;
        swap(x.data_, y.data_);
        swap(x.size_, y.size_);
    }

    // 引数を値で受け取る = ここで既にコピーが済んでいる
    Bytes& operator=(Bytes o) {
        swap(*this, o);
        return *this;
    }

    std::size_t size() const { return size_; }
    int& at(std::size_t i) { return data_[i]; }
    int at(std::size_t i) const { return data_[i]; }

private:
    std::unique_ptr<int[]> data_;
    std::size_t size_;
};

