    static int live;
    int value;
    std::string name;

    Node(int v, std::string n) : value(v), name(std::move(n)) { ++live; }
    ~Node() { --live; }
};
int Node::live = 0;

// TODO: parent と所有権を共有したまま、parent->value を指す shared_ptr を返す
std::shared_ptr<int> share_value(const std::shared_ptr<Node>& parent) {
    return std::make_shared<int>(parent->value);
}

