#include <thread>
#include <vector>
#include <cstddef>
#include <algorithm>

std::vector<int> squares_in_threads(std::size_t n) {
    std::vector<int> out(n, 0);
    std::vector<std::thread> workers;
    workers.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        workers.emplace_back([&out, i]() {
            out[i] = static_cast<int>(i * i);
        });
    }
    for (std::thread& t : workers) {
        t.join();
    }
    return out;
}

long long sum_in_threads(const std::vector<int>& v, std::size_t threads) {
    if (v.empty()) return 0;
    if (threads == 0) threads = 1;
    if (threads > v.size()) threads = v.size();

    const std::size_t chunk = (v.size() + threads - 1) / threads;
    std::vector<long long> partial(threads, 0);
    std::vector<std::thread> workers;
    workers.reserve(threads);

    for (std::size_t i = 0; i < threads; ++i) {
        const std::size_t begin = std::min(i * chunk, v.size());
        const std::size_t end = std::min(begin + chunk, v.size());
        workers.emplace_back([&v, &partial, i, begin, end]() {
            long long s = 0;
            for (std::size_t k = begin; k < end; ++k) s += v[k];
            partial[i] = s;
        });
    }
    for (std::thread& t : workers) {
        t.join();
    }

    long long total = 0;
    for (long long x : partial) total += x;
    return total;
}

description_md:
`std::thread` は **join も detach もされないまま破棄されると `std::terminate` を呼びます**。
例外で途中脱出したときも確実に join するために、スレッドを抱えて **デストラクタで join する RAII クラス** `JoinGuard` を完成させましょう。

```cpp
int result = 0;
{
    JoinGuard g(std::thread([&]{ result = 1 + 2; }));
}   // ← ここでスコープを抜けるとき join されている
result;  // => 3
```

`spawn_add(a, b)` は別スレッドで `a + b` を計算し、`JoinGuard` のおかげでスコープを抜けた時点で結果が確定しています。

