    ~JoinGuard() {
        // TODO: t_ がまだ join されていなければ join する
    }

    JoinGuard(const JoinGuard&) = delete;
    JoinGuard& operator=(const JoinGuard&) = delete;

private:
    std::thread t_;
};

int spawn_add(int a, int b) {
    int result = 0;
    {
        JoinGuard g(std::thread([&] { result = a + b; }));
    }
    return result;
}

