#include <atomic>
#include <thread>
#include <vector>

long long count_parallel(int threads, int per_thread) {
    std::atomic<long long> counter{0};
    std::vector<std::thread> workers;
    for (int i = 0; i < threads; ++i) {
        workers.emplace_back([&counter, per_thread] {
            for (int k = 0; k < per_thread; ++k) {
                ++counter;
            }
        });
    }
    for (auto& w : workers) {
        w.join();
    }
    return counter.load();
}

