#include <atomic>
#include <thread>
#include <vector>
#include <algorithm>
#include <cstddef>

long long relaxed_sum(const std::vector<int>& data, int threads) {
    if (threads < 1) threads = 1;
    const std::size_t n = data.size();
    const std::size_t chunk = (n + static_cast<std::size_t>(threads) - 1) / static_cast<std::size_t>(threads);

    std::atomic<long long> total{0};
    std::vector<std::thread> workers;
    for (int i = 0; i < threads; ++i) {
        const std::size_t begin = std::min(n, chunk * static_cast<std::size_t>(i));
        const std::size_t end = std::min(n, begin + chunk);
        if (begin >= end) continue;
        workers.emplace_back([&data, &total, begin, end] {
            long long local = 0;
            for (std::size_t k = begin; k < end; ++k) local += data[k];
            total.fetch_add(local, std::memory_order_relaxed);
        });
    }
    for (auto& w : workers) {
        w.join();
    }
    return total.load(std::memory_order_relaxed);
}

