#include <atomic>
#include <thread>

class Handoff {
public:
    void produce(int v) {
        payload_ = v;                                     // 普通の書き込み
        ready_.store(true, std::memory_order_release);    // ここまでの書き込みを「公開」する
    }

    int consume() {
        while (!ready_.load(std::memory_order_acquire)) { // 公開されるまで待つ
            std::this_thread::yield();
        }
        return payload_;                                  // payload_ は必ず見えている
    }

private:
    int payload_ = 0;                  // アトミックではない普通の変数
    std::atomic<bool> ready_{false};
};

