#include <future>
#include <vector>
#include <cstddef>

long long parallel_sum_async(const std::vector<long long>& data) {
    if (data.size() < 2) {
        long long sum = 0;
        for (long long x : data) sum += x;
        return sum;
    }

    const std::size_t mid = data.size() / 2;
    std::future<long long> right = std::async(std::launch::async, [&data, mid] {
        long long sum = 0;
        for (std::size_t i = mid; i < data.size(); ++i) sum += data[i];
        return sum;
    });

    long long left = 0;
    for (std::size_t i = 0; i < mid; ++i) left += data[i];

    return left + right.get();
}

