#include <future>
#include <thread>
#include <utility>

// 受け取った promise に n * n を入れる。
void fill_square(std::promise<int> p, int n) {
    p.set_value(n * n);
}

// a と b の 2 乗を別々のスレッドで計算し、合計を返す。
int sum_of_squares(int a, int b) {
    std::promise<int> pa;
    std::promise<int> pb;
    std::future<int> fa = pa.get_future();
    std::future<int> fb = pb.get_future();

    std::thread ta(fill_square, std::move(pa), a);
    std::thread tb(fill_square, std::move(pb), b);

    const int total = fa.get() + fb.get();

    ta.join();
    tb.join();
    return total;
}

