#include <thread>
#include <vector>
#include <cstddef>

// 1 つで 1 キャッシュラインを占め、隣と同じラインに載らないようにする
struct alignas(64) PaddedCounter {
    long long value = 0;
};

long long count_padded(int threads, int iters) {
    const std::size_t n = threads > 0 ? static_cast<std::size_t>(threads) : 0;
    std::vector<PaddedCounter> counters(n);

    std::vector<std::thread> workers;
    for (std::size_t i = 0; i < n; ++i) {
        workers.emplace_back([&counters, i, iters] {
            for (int k = 0; k < iters; ++k) {
                ++counters[i].value;
            }
        });
    }
    for (auto& w : workers) {
        w.join();
    }

    long long total = 0;
    for (const PaddedCounter& c : counters) {
        total += c.value;
    }
    return total;
}

