    std::vector<double> z;
    std::vector<int> id;
};

ParticleSoA to_soa(const std::vector<Particle>& ps) {
    ParticleSoA s;
    s.x.reserve(ps.size());
    s.y.reserve(ps.size());
    s.z.reserve(ps.size());
    s.id.reserve(ps.size());
    for (const Particle& p : ps) {
        s.x.push_back(p.x);
        s.y.push_back(p.y);
        s.z.push_back(p.z);
        s.id.push_back(p.id);
    }
    return s;
}

double sum_x_aos(const std::vector<Particle>& ps) {
