std::size_t x_stride_aos(const std::vector<Particle>& ps) {
    if (ps.size() < 2) return 0;
    const char* a = reinterpret_cast<const char*>(&ps[0].x);
    const char* b = reinterpret_cast<const char*>(&ps[1].x);
    return static_cast<std::size_t>(b - a);
}

std::size_t x_stride_soa(const ParticleSoA& s) {
    if (s.x.size() < 2) return 0;
    const char* a = reinterpret_cast<const char*>(&s.x[0]);
    const char* b = reinterpret_cast<const char*>(&s.x[1]);
    return static_cast<std::size_t>(b - a);
}

