#include <vector>
#include <cstddef>
#include <utility>

struct Tracked {
    std::vector<int> data;
    static int copy_count;
    static int move_count;

    Tracked() = default;
    explicit Tracked(std::vector<int> d) : data(std::move(d)) {}
    Tracked(const Tracked& o) : data(o.data) { ++copy_count; }
    Tracked(Tracked&& o) noexcept : data(std::move(o.data)) { ++move_count; }
    Tracked& operator=(const Tracked& o) { data = o.data; ++copy_count; return *this; }
    Tracked& operator=(Tracked&& o) noexcept { data = std::move(o.data); ++move_count; return *this; }

    static void reset() { copy_count = 0; move_count = 0; }
};

