#include <cstddef>
#include <new>
#include <vector>

struct AllocStats {
    static std::size_t allocate_calls;
    static std::size_t deallocate_calls;
    static std::size_t bytes_allocated;
    static void reset() { allocate_calls = 0; deallocate_calls = 0; bytes_allocated = 0; }
};

std::size_t AllocStats::allocate_calls = 0;
std::size_t AllocStats::deallocate_calls = 0;
std::size_t AllocStats::bytes_allocated = 0;

template <class T>
struct CountingAllocator {
    using value_type = T;

    CountingAllocator() noexcept {}
    template <class U>
    CountingAllocator(const CountingAllocator<U>&) noexcept {}

    T* allocate(std::size_t n) {
        ++AllocStats::allocate_calls;
        AllocStats::bytes_allocated += n * sizeof(T);
        return static_cast<T*>(::operator new(n * sizeof(T)));
    }

    void deallocate(T* p, std::size_t n) {
        ++AllocStats::deallocate_calls;
        (void)n;
        ::operator delete(p);
    }
};

template <class T, class U>
bool operator==(const CountingAllocator<T>&, const CountingAllocator<U>&) noexcept { return true; }
template <class T, class U>
bool operator!=(const CountingAllocator<T>&, const CountingAllocator<U>&) noexcept { return false; }

using CountedVector = std::vector<int, CountingAllocator<int>>;

long long total(const CountedVector& v) {
    long long s = 0;
    for (int x : v) s += x;
    return s;
}

