#include <cstdint>
#include <vector>

using BitSet = std::uint64_t;

BitSet make_set(const std::vector<int>& xs) {
    BitSet s = 0;
    for (int x : xs) {
        if (x >= 0 && x < 64) s |= (BitSet)1 << x;
    }
    return s;
}

BitSet set_union(BitSet a, BitSet b) { return a | b; }

BitSet set_intersection(BitSet a, BitSet b) { return a & b; }

BitSet set_difference(BitSet a, BitSet b) { return a & ~b; }

bool contains(BitSet s, int x) {
    if (x < 0 || x >= 64) return false;
    return (s >> x) & 1;
}

int set_size(BitSet s) {
    int n = 0;
    while (s != 0) {
        s &= s - 1;   // 最下位の 1 ビットを 1 個ずつ落とす
        ++n;
    }
    return n;
}

