#include <string>
#include <cstddef>

std::string repeat_join(const std::string& piece, int n, std::size_t* realloc_count) {
    std::string s;
    std::size_t count = 0;
    if (n > 0) {
        s.reserve(piece.size() * static_cast<std::size_t>(n));
        std::size_t cap = s.capacity();
        for (int i = 0; i < n; ++i) {
            s.append(piece);
            if (s.capacity() != cap) { ++count; cap = s.capacity(); }
        }
    }
    if (realloc_count != nullptr) *realloc_count = count;
    return s;
}

