#include <vector>
#include <algorithm>
#include <cstddef>
#include <utility>

class SortedSet {
public:
    explicit SortedSet(std::vector<int> keys) : keys_(std::move(keys)) {
        std::sort(keys_.begin(), keys_.end());
        keys_.erase(std::unique(keys_.begin(), keys_.end()), keys_.end());
    }

    bool contains(int key) const {
        probes_ = 0;
        std::size_t lo = 0;
        std::size_t hi = keys_.size();
        while (lo < hi) {
            std::size_t mid = lo + (hi - lo) / 2;
            ++probes_;
            if (keys_[mid] == key) return true;
            if (keys_[mid] < key) lo = mid + 1;
            else hi = mid;
        }
        return false;
    }

    std::size_t size() const { return keys_.size(); }

    std::size_t last_probe_count() const { return probes_; }

private:
    std::vector<int> keys_;
    mutable std::size_t probes_ = 0;
};

