#include <climits>

bool safe_add(int a, int b, int* out) {
    if (b > 0 && a > INT_MAX - b) return false;
    if (b < 0 && a < INT_MIN - b) return false;
    *out = a + b;
    return true;
}

bool safe_mul(int a, int b, int* out) {
    long long r = static_cast<long long>(a) * static_cast<long long>(b);
    if (r > static_cast<long long>(INT_MAX)) return false;
    if (r < static_cast<long long>(INT_MIN)) return false;
    *out = static_cast<int>(r);
    return true;
}

