#include <cmath>
#include <algorithm>

bool nearly_equal(double a, double b, double rel_tol, double abs_tol) {
    if (a == b) return true;                    // 完全一致 (無限大同士を含む)
    const double diff = std::fabs(a - b);
    if (diff <= abs_tol) return true;           // 0 付近は絶対誤差で見る
    const double scale = std::max(std::fabs(a), std::fabs(b));
    return diff <= rel_tol * scale;             // 大きい値は相対誤差で見る
}

int compare_approx(double a, double b, double rel_tol, double abs_tol) {
    if (nearly_equal(a, b, rel_tol, abs_tol)) return 0;
    return a < b ? -1 : 1;
}

