#include <string>
#include <vector>
#include <stdexcept>
#include <utility>

std::vector<std::string> g_log;

class Transaction {
public:
    explicit Transaction(std::string name) : name_(std::move(name)) {}
    ~Transaction() noexcept;
    void commit();
    void set_fail_on_rollback(bool f) { fail_on_rollback_ = f; }
private:
    void rollback() {
        if (fail_on_rollback_) throw std::runtime_error("rollback failed");
    }
    std::string name_;
    bool committed_ = false;
    bool fail_on_rollback_ = false;
};

void Transaction::commit() {
    if (name_.empty()) throw std::runtime_error("empty transaction");
    committed_ = true;
    g_log.push_back("commit:" + name_);
}

Transaction::~Transaction() noexcept {
    if (committed_) return;
    try {
        rollback();
        g_log.push_back("rollback:" + name_);
    } catch (...) {
        // 巻き戻し中かもしれない。ここで外に出したら std::terminate になる
        g_log.push_back("rollback-failed:" + name_);
    }
}

