#include <functional>
#include <vector>
#include <utility>

std::vector<std::function<int(int)>> make_scalers(const std::vector<int>& factors) {
    std::vector<std::function<int(int)>> out;
    out.reserve(factors.size());
    for (int f : factors) {
        out.push_back([f](int x) { return f * x; });   // f を値でコピーする
    }
    return out;
}

std::function<int()> deferred_sum(std::vector<int> values) {
    return [v = std::move(values)]() {                 // ムーブして持ち越す
        int total = 0;
        for (int x : v) total += x;
        return total;
    };
}

