#include <vector>
#include <stdexcept>
#include <cstddef>

int at_or(const std::vector<int>& v, int index, int fallback) {
    if (index < 0) return fallback;
    if (static_cast<std::size_t>(index) >= v.size()) return fallback;
    return v[index];        // ここでは範囲内が保証されているので [] でよい
}

int checked_at(const std::vector<int>& v, int index) {
    if (index < 0) throw std::out_of_range("negative index");
    return v.at(static_cast<std::size_t>(index));
}

