#include <utility>
#include <type_traits>

template <class T>
class Box {
public:
    Box() noexcept : ptr_(nullptr) {}
    explicit Box(T* p) noexcept : ptr_(p) {}

    ~Box() { delete ptr_; }

    Box(const Box&) = delete;             // コピー禁止 (所有権は 1 つだけ)
    Box& operator=(const Box&) = delete;

    Box(Box&& other) noexcept : ptr_(other.ptr_) {
        other.ptr_ = nullptr;             // 移動元は「空だが有効」な状態にする
    }

    Box& operator=(Box&& other) noexcept {
        if (this != &other) {
            delete ptr_;
            ptr_ = other.ptr_;
            other.ptr_ = nullptr;
        }
        return *this;
    }

    T* get() const noexcept { return ptr_; }

    T* release() noexcept {
        T* p = ptr_;
        ptr_ = nullptr;
        return p;
    }

    void reset(T* p = nullptr) noexcept {
        delete ptr_;
        ptr_ = p;
    }

    explicit operator bool() const noexcept { return ptr_ != nullptr; }
    T& operator*() const { return *ptr_; }
    T* operator->() const noexcept { return ptr_; }

private:
    T* ptr_;
};

