#include <atomic>
#include <utility>

template <class T>
class Rc {
public:
    Rc() noexcept : block_(nullptr) {}
    explicit Rc(T* p) : block_(p ? new Block(p) : nullptr) {}

    Rc(const Rc& other) noexcept : block_(other.block_) {
        if (block_) block_->count.fetch_add(1, std::memory_order_relaxed);
    }

    Rc(Rc&& other) noexcept : block_(other.block_) { other.block_ = nullptr; }

    Rc& operator=(const Rc& other) noexcept {
        Rc tmp(other);          // copy and swap
        swap(tmp);
        return *this;
    }

    Rc& operator=(Rc&& other) noexcept {
        Rc tmp(std::move(other));
        swap(tmp);
        return *this;
    }

    ~Rc() { release(); }

    long use_count() const noexcept {
        return block_ ? block_->count.load(std::memory_order_relaxed) : 0;
    }

    T* get() const noexcept { return block_ ? block_->ptr : nullptr; }
    T& operator*() const { return *block_->ptr; }

    void reset() { release(); block_ = nullptr; }

private:
    struct Block {
        T* ptr;
        std::atomic<long> count;
        explicit Block(T* p) : ptr(p), count(1) {}
    };

    void release() noexcept {
        if (!block_) return;
        if (block_->count.fetch_sub(1, std::memory_order_acq_rel) == 1) {
            delete block_->ptr;     // 最後の 1 人だったので解放する
            delete block_;
        }
    }

    void swap(Rc& other) noexcept {
        Block* tmp = block_;
        block_ = other.block_;
        other.block_ = tmp;
    }

    Block* block_;
};

