#include <cstddef>
#include <memory>

class SmallVec {
public:
    static constexpr std::size_t kInline = 4;

    SmallVec() : heap_(nullptr), data_(inline_), size_(0), cap_(kInline) {}

    void push_back(int v) {
        if (size_ == cap_) grow();
        data_[size_] = v;
        ++size_;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return cap_; }
    bool is_inline() const { return data_ == inline_; }
    int operator[](std::size_t i) const { return data_[i]; }

private:
    void grow() {
        const std::size_t new_cap = cap_ * 2;
        std::unique_ptr<int[]> buf(new int[new_cap]);
        for (std::size_t i = 0; i < size_; ++i) buf[i] = data_[i];
        heap_ = std::move(buf);      // 古いヒープ領域はここで解放される
        data_ = heap_.get();
        cap_ = new_cap;
    }

    int inline_[kInline] = {};
    std::unique_ptr<int[]> heap_;
    int* data_;
    std::size_t size_;
    std::size_t cap_;
};

