#include <cstddef>
#include <vector>

class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity) : buf_(capacity), head_(0), size_(0) {}

    bool push(int v) {
        if (full()) return false;                    // 容量 0 もここで弾ける
        buf_[(head_ + size_) % buf_.size()] = v;     // 末尾 = 先頭 + 個数
        ++size_;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = buf_[head_];
        head_ = (head_ + 1) % buf_.size();
        --size_;
        return true;
    }

    std::size_t size() const { return size_; }
    std::size_t capacity() const { return buf_.size(); }
    bool empty() const { return size_ == 0; }
    bool full() const { return size_ == buf_.size(); }

private:
    std::vector<int> buf_;
    std::size_t head_;   // 次に取り出す位置
    std::size_t size_;
};

