        [](Idle) { return std::string("idle"); },
        [](Running) { return std::string("running"); },
        [](Done) { return std::string("done"); }
    }, s);
}

int elapsed_of(const State& s) {
    return std::visit(overloaded{
        [](Idle) { return 0; },
        [](Running r) { return r.elapsed; },
        [](Done d) { return d.total; }
    }, s);
}

