#include <vector>
#include <functional>
#include <optional>
#include <utility>

class Lazy {
public:
    explicit Lazy(std::vector<int> src) : src_(std::move(src)) {}

    Lazy map(std::function<int(int)> f) const {
        Lazy out = *this;
        out.stages_.push_back([f](int x) { return std::optional<int>(f(x)); });
        return out;
    }

    Lazy filter(std::function<bool(int)> p) const {
        Lazy out = *this;
        out.stages_.push_back([p](int x) {
            return p(x) ? std::optional<int>(x) : std::optional<int>();
        });
        return out;
    }

    std::vector<int> to_vector() const {
        std::vector<int> out;
        for (int x : src_) {
            std::optional<int> r = run_stages(x);
            if (r) out.push_back(*r);
        }
        return out;
    }

    std::optional<int> first() const {
        for (int x : src_) {
            std::optional<int> r = run_stages(x);
            if (r) return r;                 // ここで走査を打ち切る
        }
        return std::nullopt;
    }

private:
    std::optional<int> run_stages(int x) const {
        std::optional<int> cur(x);
        for (const std::function<std::optional<int>(int)>& st : stages_) {
            cur = st(*cur);
            if (!cur) return std::nullopt;   // filter で落ちた
        }
        return cur;
    }

    std::vector<int> src_;
    std::vector<std::function<std::optional<int>(int)>> stages_;
};

