#include <unordered_map>
#include <mutex>
#include <functional>
#include <cstddef>

class Memo {
public:
    int get(int key, const std::function<int(int)>& compute) {
        {
            std::lock_guard<std::mutex> lock(mu_);
            std::unordered_map<int, int>::const_iterator it = cache_.find(key);
            if (it != cache_.end()) return it->second;
        }   // ここでロックを手放す

        const int value = compute(key);     // ロックを持たずに計算する

        std::lock_guard<std::mutex> lock(mu_);
        // 待っている間に他スレッドが入れていれば、そちらを正とする
        return cache_.emplace(key, value).first->second;
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mu_);
        return cache_.size();
    }

    bool contains(int key) const {
        std::lock_guard<std::mutex> lock(mu_);
        return cache_.find(key) != cache_.end();
    }

private:
    mutable std::mutex mu_;
    std::unordered_map<int, int> cache_;
};
